script:
body { background: var(--2d89eb17-5c6b-4a9a-83ec-a4dd44a2268b, #F6F6F5); }
button { cursor: pointer; }
button:disabled { opacity: 0.45; cursor: not-allowed; }
a, button { transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease, border-color 0.15s ease; }
a:hover { opacity: 0.7; }
:focus-visible { outline: 2px solid var(--24e6b6d1-a2d3-4b17-adc9-4489ec49a8c3, #161616); outline-offset: 2px; }
[data-shop="variant-option"][data-selected="true"] {
	background: var(--59d1d517-3c82-4bd4-be54-25f6174236f5, #161616);
	color: var(--7b7e4d6b-dc17-45f3-8109-367429a9049b, #FFFFFF);
	border-color: var(--59d1d517-3c82-4bd4-be54-25f6174236f5, #161616);
}
[data-shop="cart-count"][data-empty="true"] { display: none; }
a[data-active="true"] {
	background: var(--59d1d517-3c82-4bd4-be54-25f6174236f5, #161616);
	color: var(--7b7e4d6b-dc17-45f3-8109-367429a9049b, #FFFFFF);
	border-color: var(--59d1d517-3c82-4bd4-be54-25f6174236f5, #161616);
}
input, textarea { font-family: inherit; }
